    /*
     * Assign a Device
     * 
     * @param	parentId	UUID
     * @param	assignment 	MedicalDevice 
     * @return	SoftwareUpdate
     */
    public SoftwareUpdate assignDevice( UUID parentId, MedicalDevice assignment ) {
	    LOGGER.info("assigning Device as " + assignment.toString() );

	    SoftwareUpdate parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( MedicalDevice.class, assignment.getMedicalDeviceId());

	    // ------------------------------------------
		// assign the Device to the parent entity
		// ------------------------------------------ 
	    parentEntity.setDevice( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Device
	 * 
	 * @param	parentId		UUID
	 * @return	SoftwareUpdate
	 */
	public SoftwareUpdate unAssignDevice( UUID parentId ) {
		SoftwareUpdate parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Device on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Device on the parent entithy
		// ------------------------------------------     
	    parentEntity.setDevice(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}




